insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('1863611a-ff86-4865-9815-39f8c08ae0d5', '724606fd-d697-4c09-82ce-b6c5099d7205', $$inleiding: heffing op vervuilende productie (markt A) en subsidie op schone productie (markt B)$$,
   $$economie-vwo-2024-i-duurzaamheid-stimuleren-context1.png$$,
   $$De overheid van een land heeft met de overheden van andere landen een afspraak gemaakt om de CO₂-uitstoot aanzienlijk te verminderen. Een politicus stelt een combinatie van maatregelen voor om het afgesproken doel te behalen: het instellen van heffingen op vervuilende productie (markt A) en het subsidiëren van schone productie (markt B). Een econoom onderzoekt deze twee markten van volledige mededinging.$$, 'inline'),
  ('f113ec91-042b-43ee-b6ce-d1575e35c4b9', '724606fd-d697-4c09-82ce-b6c5099d7205', $$figuur 1: marktsituatie van A, met en zonder heffing$$,
   $$economie-vwo-2024-i-duurzaamheid-stimuleren-context2.png$$,
   $$Figuur 1 Marktsituatie van A, met en zonder heffing:
verticale as: prijs (in €), 0 tot 36; horizontale as: hoeveelheid x 1.000 stuks, 0 tot 100
vraag: van (0; 28) dalend naar (100; 8)
aanbod zonder heffing: van (0; 8) stijgend naar (100; 28)
aanbod met heffing (stippellijn): van (0; 12) stijgend naar (100; 32)
vraag en aanbod zonder heffing snijden bij (50; 18); vraag en aanbod met heffing snijden bij (40; 20)$$, 'inline'),
  ('8d4083ac-0cfa-4447-841f-39af0e72e2cf', '724606fd-d697-4c09-82ce-b6c5099d7205', $$figuur 2: marktsituatie van B, met en zonder subsidie$$,
   $$economie-vwo-2024-i-duurzaamheid-stimuleren-context3.png$$,
   $$Figuur 2 Marktsituatie van B, met en zonder subsidie:
verticale as: prijs (in €); horizontale as: hoeveelheid x 1.000 stuks (zonder getallen)
Dalende vraaglijn; stijgende lijn aanbod zonder subsidie; evenwijdige stippellijn aanbod met subsidie rechts/onder de lijn zonder subsidie.$$, 'inline'),
  ('1673c219-8c56-4795-8bc1-3d471d220e17', '724606fd-d697-4c09-82ce-b6c5099d7205', $$vervuilende productie leidt tot maatschappelijke kosten$$,
   $$economie-vwo-2024-i-duurzaamheid-stimuleren-context4.png$$,
   $$De vervuilende productie van product A leidt tot maatschappelijke kosten.$$, 'inline'),
  ('544e0bec-2c2e-4f43-9300-44b9445cc8e4', '724606fd-d697-4c09-82ce-b6c5099d7205', $$vraag- en aanbodfunctie van product B$$,
   $$economie-vwo-2024-i-duurzaamheid-stimuleren-context5.png$$,
   $$Voor product B geldt: Qa = 2p – 20 Qv = –2p + 80 Qa = aangeboden hoeveelheid zonder subsidie (x 1.000 stuks) Qv = gevraagde hoeveelheid (x 1.000 stuks) P = de prijs per product in euro’s$$, 'inline'),
  ('103d636d-f5b7-40a2-9e71-d1d2056c5d88', '724606fd-d697-4c09-82ce-b6c5099d7205', $$subsidie van € 5 per product en CO₂-uitstoot per product A en B$$,
   $$economie-vwo-2024-i-duurzaamheid-stimuleren-context6.png$$,
   $$De subsidie bedraagt € 5 per product. De CO₂-uitstoot per product A is 6 kilogram, en per product B is het 2 kilogram.$$, 'inline'),
  ('4a486b00-b0ae-4512-bddb-4d2bb143c7a0', '724606fd-d697-4c09-82ce-b6c5099d7205', $$bedrijf Knop: constante en proportioneel variabele kosten per product$$,
   $$economie-vwo-2024-i-duurzaamheid-stimuleren-context7.png$$,
   $$De econoom bekijkt hoe de heffing zal uitwerken voor een individueel bedrijf op de markt van product A (zie figuur 1). Bedrijf Knop had voor de heffing € 12 constante kosten per product en € 5 proportioneel variabele kosten per product.$$, 'inline'),
  ('37576af9-8ef7-4e8c-9242-ab10d8be70cd', '724606fd-d697-4c09-82ce-b6c5099d7205', $$kanttekening: positieve kruislingse prijselasticiteit van A en B$$,
   $$economie-vwo-2024-i-duurzaamheid-stimuleren-context8.png$$,
   $$De econoom plaatst een kanttekening bij haar analyse: “De subsidie op markt B heeft ook effect op markt A. De kruislingse prijselasticiteiten zijn positief voor product A en B. Als de prijs van product B daalt, zal de verwachte CO₂-uitstoot van product A veranderen.”$$, 'inline'),
  ('190a1cd7-2e27-4498-9618-27af3be1bf9e', '724606fd-d697-4c09-82ce-b6c5099d7205', $$uitwerkbijlage vraag 4: figuur 1 en figuur 2$$,
   $$economie-vwo-2024-i-duurzaamheid-stimuleren-context9.png$$,
   $$uitwerkbijlage vraag 4
Figuur 1 Marktsituatie van A, met en zonder heffing: kopie van figuur 1 (vraag, aanbod zonder heffing, aanbod met heffing; prijs in €, hoeveelheid x 1.000 stuks)
Figuur 2 Marktsituatie van B, met en zonder subsidie: kopie van figuur 2 (vraag, aanbod zonder subsidie, aanbod met subsidie)$$, 'uitwerkbijlage'),
  ('68a83c32-af18-4eb4-a0aa-2846a1f3a3ac', 'f1071dac-23c9-4394-84b5-5fda988cdc6f', $$inleiding: oplopende staatsschuld van Maecenates in 2011-2020$$,
   $$economie-vwo-2024-i-staat-van-de-schulden-context1.png$$,
   $$Maecenates is een land dat al jaren kampt met een oplopende staatsschuld. Economen Falco en Colomba analyseren de houdbaarheid van de overheidsfinanciën en de doelmatigheid van de overheidsbestedingen in de periode 2011-2020 aan de hand van de gegevens in figuur 1.$$, 'inline'),
  ('6818b213-fc83-4622-8e40-b1cb4f22fb32', 'f1071dac-23c9-4394-84b5-5fda988cdc6f', $$figuur 1: staatsschuldquote en nominale rente op staatsobligaties, met formule staatsschuldquote$$,
   $$economie-vwo-2024-i-staat-van-de-schulden-context2.png$$,
   $$Figuur 1 Staatsschuldquote en nominale rente Maecenates
Staafdiagram (staatsschuldquote, linkeras 135% tot 180%) en lijn (nominaal rentepercentage op staatsobligaties, rechteras 1,00% tot 2,80%), jaren 2011-2020.
Staatsschuldquote stijgt van ca. 149,5% (2011) tot ca. 175% (2020), met een kleine daling in 2017.
Nominaal rentepercentage stijgt van ca. 1,72% (2011) tot ca. 2,40% (2020), met een kleine daling in 2017.
(exacte waarden: zie de figuur)
Staatsschuldquote = (Staatsschuld / BBP) x 100%$$, 'inline'),
  ('6c5819df-48b1-44e9-aa67-e6127824fa6f', 'f1071dac-23c9-4394-84b5-5fda988cdc6f', $$bewering Falco: verband tussen staatsschuldquote en nominale rente$$,
   $$economie-vwo-2024-i-staat-van-de-schulden-context3.png$$,
   $$Econoom Falco beweert dat er een verband bestaat tussen de staatsschuldquote en de ontwikkeling van het nominaal rentepercentage op staatsobligaties.$$, 'inline'),
  ('81ff5127-6d63-4c9b-876c-04f8c263d99c', 'f1071dac-23c9-4394-84b5-5fda988cdc6f', $$dienstverlening onder druk bij rente-uitgaven boven 10% van de overheidsuitgaven; overheidsuitgaven 43% van bbp$$,
   $$economie-vwo-2024-i-staat-van-de-schulden-context4.png$$,
   $$Econoom Falco beweert dat de dienstverlening van de overheid onder druk komt te staan, als de rente-uitgaven groter worden dan 10% van de overheidsuitgaven. De overheidsuitgaven van Maecenates bedragen 43% van het bbp in 2020.$$, 'inline'),
  ('bebd8bb6-6cc5-49be-b6ee-f8485c17b316', 'f1071dac-23c9-4394-84b5-5fda988cdc6f', $$verhoging inkomstenbelasting: uitverdieneffect en grotere belastingwig$$,
   $$economie-vwo-2024-i-staat-van-de-schulden-context5.png$$,
   $$Falco wil dat de staatsschuldquote afneemt door een verhoging van de inkomstenbelasting. Colomba vindt dat een verhoging van de inkomstenbelasting door een uitverdieneffect en een grotere belastingwig, een beperkt effect heeft op de staatsschuld.$$, 'inline'),
  ('ba96f516-863c-49d0-a3bc-ac15ff72adc5', 'f1071dac-23c9-4394-84b5-5fda988cdc6f', $$stelling Colomba: overheidsinvesteringen in publiek kapitaal$$,
   $$economie-vwo-2024-i-staat-van-de-schulden-context6.png$$,
   $$Colomba stelt: “De overheidsinvesteringen kunnen via het publiek kapitaal op termijn tot een lagere staatsschuldquote leiden.”$$, 'inline'),
  ('142c42fe-9704-4067-ba8c-8d9b063c3fbf', 'f1071dac-23c9-4394-84b5-5fda988cdc6f', $$positief overheidssaldo leidt via de vermogensmarkt tot hogere bestedingen$$,
   $$economie-vwo-2024-i-staat-van-de-schulden-context7.png$$,
   $$Bezuinigingen van de overheid verlagen de binnenlandse bestedingen en leiden tot een positief overheidssaldo. Het positieve overheidssaldo leidt via de vermogensmarkt ertoe dat de binnenlandse bestedingen toch kunnen toenemen.$$, 'inline'),
  ('8267ec04-8148-4766-9d72-414c0d38df51', 'c0c89bf9-a691-41fe-97b0-655b95558f6c', $$inleiding: valutarisico bij betaling in vreemde valuta$$,
   $$economie-vwo-2024-i-valutaverzekering-context1.png$$,
   $$Wanneer Nederlandse exporteurs handelen met bedrijven buiten de eurozone, kan gekozen worden voor betaling in euro’s of in de vreemde valuta. Als wordt afgesproken om te betalen in vreemde valuta, bestaat het risico dat tussen het moment van afsluiten van de koopovereenkomst en het moment van betaling de wisselkoersen veranderen. Dit is een valutarisico dat voor Nederlandse exporteurs nadelig kan uitpakken.$$, 'inline'),
  ('b7697fe7-4196-4d23-a069-0247eeb32345', 'c0c89bf9-a691-41fe-97b0-655b95558f6c', $$Tradesure introduceert een valutaverzekering bij export$$,
   $$economie-vwo-2024-i-valutaverzekering-context2.png$$,
   $$De verzekeraar Tradesure introduceert een nieuwe verzekering: de valutaverzekering bij export. De voorwaarden staan in tabel 1.$$, 'inline'),
  ('4fc51b9f-c5d3-4444-a2cc-c055b6a83007', 'c0c89bf9-a691-41fe-97b0-655b95558f6c', $$tabel 1: voorwaarden valutaverzekering bij export$$,
   $$economie-vwo-2024-i-valutaverzekering-context3.png$$,
   $$Tabel 1 Voorwaarden valutaverzekering bij export
Verzekering Een exporteur kan naast het exportcontract ook een valutaverzekering afsluiten als de betaling van het exportcontract in vreemde valuta wordt gedaan. De verzekering wordt afgesloten tegen het risico van een koerswijziging ten opzichte van de garantiekoers (= de op dat moment geldende koers). Verzekerde Standaardvaluta’s: wisselkoersen van westerse en relatief valuta stabiele ontwikkelingslanden.
Hogere risico valuta’s: wisselkoersen van instabielere landen. Premie Er is een vaste premie van 0,5% van de verzekerde contractsom, tot een maximumpremie van € 125.000.
Daarnaast is er een variabele premie van 0,16% per maand van de contractsom voor de standaardvaluta’s en 0,25% per maand van de contractsom voor de hogere risico valuta’s. Uitkering Wanneer bij betaling van het exportcontract het ontvangen bedrag in euro’s lager is dan het verzekerde bedrag in euro’s tegen de garantiekoers, keert Tradesure het verschil uit.$$, 'inline'),
  ('0bff82f3-93e4-4c44-adfb-00c7541b9082', 'c0c89bf9-a691-41fe-97b0-655b95558f6c', $$Arco onderhandelt al maanden met Tradesure$$,
   $$economie-vwo-2024-i-valutaverzekering-context4.png$$,
   $$Arco is een bedrijf dat handelt in tweedehands-landbouwapparatuur. Arco onderhandelt al enkele maanden met Tradesure over een aantal voorwaarden.$$, 'inline'),
  ('f5b433de-3aed-4657-96f7-71c961358801', 'c0c89bf9-a691-41fe-97b0-655b95558f6c', $$exportcontract van € 12 miljoen in Rwandese Frank, betaling op 1-7-2023$$,
   $$economie-vwo-2024-i-valutaverzekering-context5.png$$,
   $$Arco sluit op 1-1-2023 een exportcontract met een bedrijf uit Rwanda voor de levering van € 12 miljoen aan landbouwapparatuur. Arco ontvangt van het bedrijf het bedrag in Rwandese Frank (RF), volgens Tradesure een hogere risico valuta. Daarom sluit Arco een valutaverzekering af bij Tradesure op 1-1-2023. Het bedrijf uit Rwanda betaalt op 1-7-2023.$$, 'inline'),
  ('78f55aa2-b6d5-416a-aa2b-d1a27c6391a8', 'c0c89bf9-a691-41fe-97b0-655b95558f6c', $$figuur 1: verwachte ontwikkeling wisselkoers van de euro in RF$$,
   $$economie-vwo-2024-i-valutaverzekering-context6.png$$,
   $$Figuur 1 Verwachte ontwikkeling wisselkoers van de euro in RF
verticale as: € 1 in RF (800 tot 1.200); horizontale as: tijd
1-1-2023: 980
1-2-2023: 985
1-3-2023: 993
1-4-2023: 1.042
1-5-2023: 1.036
1-6-2023: 1.021
1-7-2023: 1.024
1-8-2023: 1.047
1-9-2023: 1.051
1-10-2023: 1.111
1-11-2023: 1.142
1-12-2023: 1.155$$, 'inline'),
  ('4754d970-e373-4e97-8ee1-3f6cfb897215', '4c8cf0fa-7122-41aa-880a-1d8112ef7374', $$inleiding: Westland wil inkomsten- en winstbelasting verlagen$$,
   $$economie-vwo-2024-i-onder-de-motorkap-context1.png$$,
   $$Westland en Oostland hebben na jaren van economische groei nu de potentiële productie bereikt. Binnenkort zijn er verkiezingen in Westland. De regering van Westland wil de tarieven van de inkomstenbelasting en de winstbelasting verlagen.$$, 'inline'),
  ('4c588528-f135-4f5f-96ae-b137988afa2e', '4c8cf0fa-7122-41aa-880a-1d8112ef7374', $$centrale bank van Oostland verandert de inflatiedoelstelling$$,
   $$economie-vwo-2024-i-onder-de-motorkap-context2.png$$,
   $$In Oostland heeft de centrale bank besloten om de inflatiedoelstelling te veranderen. De centrale bank van Oostland past daarom het monetair beleid aan.$$, 'inline'),
  ('cb1c0bb3-85bb-4ad7-a94a-5771ff648aee', '4c8cf0fa-7122-41aa-880a-1d8112ef7374', $$analyse met het IS-MB-GA-model; Y₀ = Y*$$,
   $$economie-vwo-2024-i-onder-de-motorkap-context3.png$$,
   $$Een wetenschapper gebruikt het IS-MB-GA model om de gevolgen te analyseren van beide beleidsvoornemens (zie figuren 1 en 2). De wetenschapper neemt voor beide landen aan dat Y₀ = Y*.$$, 'inline'),
  ('cf2f1289-bc7f-4c49-b4f2-1ceb924a66d4', '4c8cf0fa-7122-41aa-880a-1d8112ef7374', $$figuur 1 en figuur 2: IS-MB-GA-model Westland en Oostland$$,
   $$economie-vwo-2024-i-onder-de-motorkap-context4.png$$,
   $$Figuur 1 Model Westland en Figuur 2 Model Oostland
Westland, bovenste diagram: r (0 tot 14) tegen Y (0 tot 900); dalende IS₀ en (rechts daarvan, pijl naar rechts) IS₁; horizontale MB₀ bij r = 4; IS₀ snijdt MB₀ bij Y = 500.
Westland, onderste diagram: π (0 tot 7) tegen Y; stijgende GA₀ (van ca. 0,8 bij Y = 0 tot ca. 5,2 bij Y = 820); stippellijn bij Y₀ = 500.
Oostland, bovenste diagram: dalende IS₀; horizontale MB₀ bij r = 4 en MB₁ bij r = 2 (pijl omlaag); IS₀ snijdt MB₀ bij Y = 500.
Oostland, onderste diagram: zelfde GA₀ als Westland; stippellijn bij Y₀ = 500.
De reële rente (r) en inflatie (π) zijn in procenten. Het reële inkomen / de reële productie (Y) is in miljarden.$$, 'inline'),
  ('c5744c6e-b59f-457b-bc62-161a51f3ccd1', '4c8cf0fa-7122-41aa-880a-1d8112ef7374', $$Westland: IS₀ verschuift naar IS₁$$,
   $$economie-vwo-2024-i-onder-de-motorkap-context5.png$$,
   $$Door het plan van de regering van Westland om de inkomstenbelasting te verlagen verschuift IS₀ naar IS₁.$$, 'inline'),
  ('895c1d0e-edd5-4d65-bf5b-8b20e162a5b0', '4c8cf0fa-7122-41aa-880a-1d8112ef7374', $$Oostland: MB₀ verschuift naar MB₁$$,
   $$economie-vwo-2024-i-onder-de-motorkap-context6.png$$,
   $$Door de veranderde inflatiedoelstelling van de Oostlandse centrale bank verschuift MB₀ naar MB₁.$$, 'inline'),
  ('7b54428f-e637-4cd9-8ad8-53dfd3588cb4', '4c8cf0fa-7122-41aa-880a-1d8112ef7374', $$IS-curve en ruilen over de tijd$$,
   $$economie-vwo-2024-i-onder-de-motorkap-context7.png$$,
   $$De IS-curve geeft het verband weer tussen de reële rente en het reële inkomen. Hier is sprake van ruilen over de tijd.$$, 'inline'),
  ('c6f362a1-ae3b-4ef6-bf99-4ebffc4a8167', '4c8cf0fa-7122-41aa-880a-1d8112ef7374', $$beide economieën keren na één renteaanpassing terug naar potentiële productie$$,
   $$economie-vwo-2024-i-onder-de-motorkap-context8.png$$,
   $$De wetenschapper stelt dat beide economieën na één renteaanpassing terugkeren naar de potentiële productie. In Oostland zal er een evenwicht ontstaan bij MB₀ = MB₂. In Westland zal een ander evenwicht ontstaan omdat daar ander beleid is gevoerd.$$, 'inline'),
  ('d59fbee7-a146-4ca6-82a0-44082c823b37', '4c8cf0fa-7122-41aa-880a-1d8112ef7374', $$conclusie: slechts één van drie variabelen verschilt$$,
   $$economie-vwo-2024-i-onder-de-motorkap-context9.png$$,
   $$Het model laat drie variabelen zien: de reële productie, de reële rente en de inflatie. De wetenschapper concludeert: “Als ik enkel naar de figuren kijk, zie ik dat slechts één van deze drie variabelen verschilt als beide economieën weer naar Y* terug zijn gekeerd.”$$, 'inline'),
  ('cf03a078-db15-4b78-b153-f63a43cb1d07', '4c8cf0fa-7122-41aa-880a-1d8112ef7374', $$uitwerkbijlage vraag 21: figuur 3 en tabel evenwichtswaarden$$,
   $$economie-vwo-2024-i-onder-de-motorkap-context10.png$$,
   $$uitwerkbijlage vraag 21
Figuur 3 Model Westland: kopie van figuur 1 (IS₀, IS₁, MB₀ bij r = 4, GA₀, Y₀ = 500)
Evenwichtswaarden bij Y*: invultabel met kolommen Westland en Oostland en rijen inflatie en reële rente$$, 'uitwerkbijlage'),
  ('14ea9ccc-ee25-428c-b6b8-065ef229486d', '1aacfa50-c3f5-418d-92e1-2a0ef56a9aa7', $$inleiding: middeleeuwse vismarkt met veel kleine aanbieders$$,
   $$economie-vwo-2024-i-vissen-naar-winst-context1.png$$,
   $$Een econoom maakt een analyse van de ontwikkeling van de vismarkt in een regio door de eeuwen heen. De vismarkt in de middeleeuwen (zie figuur 1) wordt gekenmerkt door veel kleine aanbieders. De individuele consumenten kijken vanwege armoede enkel naar de prijs.$$, 'inline'),
  ('50e2a4d1-b751-4f90-9495-cc9cd5ef5ccb', '1aacfa50-c3f5-418d-92e1-2a0ef56a9aa7', $$figuur 1: dagelijkse vismarkt in de middeleeuwen$$,
   $$economie-vwo-2024-i-vissen-naar-winst-context2.png$$,
   $$Figuur 1 Dagelijkse vismarkt in de middeleeuwen
verticale as: prijs van vis in koperstukken; horizontale as: aantal vissen in miljoenen (0 tot 13)
Dalende vraaglijn en stijgende aanbodlijn snijden bij prijs 2 en 7 miljoen vissen.$$, 'inline'),
  ('ed06cb10-f59f-41f0-8f45-8c37382da59a', '1aacfa50-c3f5-418d-92e1-2a0ef56a9aa7', $$kostenfunctie van een individuele visser$$,
   $$economie-vwo-2024-i-vissen-naar-winst-context3.png$$,
   $$Alle individuele vissers hebben de volgende kostenfunctie: TK = 0,005q² + 0,25q + 153,12 TK = totale kosten in koperstukken q = het aantal vissen$$, 'inline'),
  ('be366534-a364-4a3d-9ff2-ac1c04bb28d7', '1aacfa50-c3f5-418d-92e1-2a0ef56a9aa7', $$elke visser streeft naar maximale winst$$,
   $$economie-vwo-2024-i-vissen-naar-winst-context4.png$$,
   $$De econoom gaat er in het model vanuit dat elke individuele visser streeft naar maximale winst.$$, 'inline'),
  ('1a72af48-2ad6-4727-8fb0-b7a258d2b0b0', '1aacfa50-c3f5-418d-92e1-2a0ef56a9aa7', $$beweringen over prijselasticiteit en monopolistische concurrentie$$,
   $$economie-vwo-2024-i-vissen-naar-winst-context5.png$$,
   $$In de late middeleeuwen worden de consumenten welvarender en kopen ze meer vis. De econoom beweert: i. Door de toegenomen welvaart verandert de prijselasticiteit van de vraag naar vis. ii. Door de toegenomen welvaart ontstaat een markt van monopolistische concurrentie.$$, 'inline'),
  ('5623edaa-5788-4483-91e7-34673a2faa90', '1aacfa50-c3f5-418d-92e1-2a0ef56a9aa7', $$oligopolie van Dirdam en Nednol$$,
   $$economie-vwo-2024-i-vissen-naar-winst-context6.png$$,
   $$In de twintigste eeuw vinden er grote technologische ontwikkelingen plaats waardoor schepen sneller meer vis binnenhalen. Door deze schaalvoordelen ontstaat een oligopolistische markt. Visserijen Dirdam en Nednol domineren de markt in de regio. Beide visserijen kunnen hun prijzen verlagen of handhaven (zie matrix 1).$$, 'inline'),
  ('3eee1762-a137-489d-88d4-e3b24ce84dae', '1aacfa50-c3f5-418d-92e1-2a0ef56a9aa7', $$matrix 1: winsten van Dirdam en Nednol$$,
   $$economie-vwo-2024-i-vissen-naar-winst-context7.png$$,
   $$Matrix 1 Winsten van Dirdam en Nednol in miljoenen €
(eerste getal: Dirdam; tweede getal, cursief: Nednol)
Dirdam handhaaft de prijs, Nednol handhaaft de prijs: 30 ; 10
Dirdam handhaaft de prijs, Nednol verlaagt de prijs: 14 ; 20
Dirdam verlaagt de prijs, Nednol handhaaft de prijs: 33 ; −2
Dirdam verlaagt de prijs, Nednol verlaagt de prijs: 19 ; 6$$, 'inline'),
  ('8d98adfb-f499-408a-b1e1-1e4920790e07', '1aacfa50-c3f5-418d-92e1-2a0ef56a9aa7', $$kartel Dirdam en Nednol; Syrap kan toetreden$$,
   $$economie-vwo-2024-i-vissen-naar-winst-context8.png$$,
   $$Na enkele jaren vormen Dirdam en Nednol een kartel. Syrap kan toetreden tot de vismarkt met een lagere prijs of de kartelprijs. De econoom presenteert spelboom 1 met daarin de keuzes.$$, 'inline'),
  ('c2f15b15-597d-40a3-bebc-5d4251272323', '1aacfa50-c3f5-418d-92e1-2a0ef56a9aa7', $$spelboom 1: winsten Syrap, Nednol en Dirdam, met toelichting$$,
   $$economie-vwo-2024-i-vissen-naar-winst-context9.png$$,
   $$Spelboom 1 Winsten Syrap, Nednol en Dirdam in miljoenen €
Eerst kiest Syrap (kartelprijs of lagere prijs), dan Nednol (= of -), dan Dirdam (= of -). Uitbetalingen (Syrap, Nednol, Dirdam):
kartelprijs, Nednol =, Dirdam =: 30, 20, 40
kartelprijs, Nednol =, Dirdam -: 15, 15, 45
kartelprijs, Nednol -, Dirdam =: 20, 25, 35
kartelprijs, Nednol -, Dirdam -: 10, 17, 40
lagere prijs, Nednol =, Dirdam =: 50, 10, 20
lagere prijs, Nednol =, Dirdam -: 40, 5, 30
lagere prijs, Nednol -, Dirdam =: 35, 15, 20
lagere prijs, Nednol -, Dirdam -: 14, 7, 28
De = symbolen geven aan waar Nednol / Dirdam ervoor kiezen hun prijs gelijk te houden aan de eerdere kartelprijs.
De – symbolen geven aan waar Nednol / Dirdam ervoor kiezen hun prijs te verlagen ten opzichte van de eerdere kartelprijs.$$, 'inline'),
  ('9c776822-a567-4524-ad0c-65d8e8ffa8a1', '75eb3305-472e-4b8d-96ae-3e84b356c577', $$inleiding: modellen voor groei op korte en lange termijn$$,
   $$economie-vwo-2024-i-groeien-tot-de-top-context1.png$$,
   $$Een econoom kijkt met behulp van twee vereenvoudigde modellen naar de economische groei op korte termijn (figuur 1) en op de lange termijn (figuur 2). Met behulp van deze modellen kan de econoom onderzoeken hoe de economische groei kan worden gestimuleerd.$$, 'inline'),
  ('426a4695-cf7d-4fbb-ae1b-f04ab9c1638a', '75eb3305-472e-4b8d-96ae-3e84b356c577', $$figuur 1: economische kringloop met legenda$$,
   $$economie-vwo-2024-i-groeien-tot-de-top-context2.png$$,
   $$Figuur 1 Economische kringloop (pijlen zijn geldstromen)
Schema: Y (nationaal inkomen) gaat via pijlen naar B, C en M; B gaat naar C; Co, Io en Oo gaan naar C, I en O; de bestedingen C + I + O + E − M vormen samen EV (effectieve vraag, stippellijn) die Y bepaalt.
Legenda: Y nationaal inkomen; EV effectieve vraag; C consumptie; I investeringen; O overheidsbestedingen; E export; M import; B belastingen; Co autonome consumptie; Io autonome investeringen; Oo autonome overheidsbestedingen$$, 'inline'),
  ('6f35e5e0-c76d-4ec9-8442-20a56b1e55e4', '75eb3305-472e-4b8d-96ae-3e84b356c577', $$twee opties: autonome overheidsbestedingen of autonome consumptie stimuleren$$,
   $$economie-vwo-2024-i-groeien-tot-de-top-context3.png$$,
   $$De econoom analyseert met behulp van figuur 1 twee opties om de economische groei op korte termijn te stimuleren:
− de autonome overheidsbestedingen stimuleren.
− de autonome consumptie stimuleren.$$, 'inline'),
  ('e96bc0cc-c482-48b3-8914-bf05b8cf6f31', '75eb3305-472e-4b8d-96ae-3e84b356c577', $$productiefunctie Y = A*f(K,L) met verklaring symbolen$$,
   $$economie-vwo-2024-i-groeien-tot-de-top-context4.png$$,
   $$De economische groei op lange termijn kan worden bestudeerd met behulp van de productiefunctie: Y = A*f(K,L) waarbij: Y = potentieel nationaal inkomen
A = factorproductiviteit K = de hoeveelheid beschikbaar kapitaal L = de hoeveelheid beschikbare arbeid$$, 'inline'),
  ('259c6f60-ef5e-4809-8e72-7c4bd8d93f62', '75eb3305-472e-4b8d-96ae-3e84b356c577', $$figuur 2: productiefunctie Y₁ en Y₂ met legenda$$,
   $$economie-vwo-2024-i-groeien-tot-de-top-context5.png$$,
   $$Figuur 2 Productiefunctie
verticale as: Y; horizontale as: arbeid L
Twee stijgende, steeds vlakker lopende curven: Y₂ (doorgetrokken) ligt boven Y₁ (stippellijn).
Legenda:
Y₁ = de productiefunctie in de uitgangssituatie
Y₂ = de productiefunctie na het stimuleren van R&D-investeringen$$, 'inline'),
  ('7a0175ba-12f2-498a-9e7f-bf6b72779abc', '75eb3305-472e-4b8d-96ae-3e84b356c577', $$conclusie: R&D verhoogt de totale factorproductiviteit$$,
   $$economie-vwo-2024-i-groeien-tot-de-top-context6.png$$,
   $$De econoom concludeert: “Door de R&D-investeringen te stimuleren, kan de totale factorproductiviteit op lange termijn stijgen. Daardoor zal de productiefunctie in figuur 2 van Y₁ naar Y₂ verschuiven.”$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('638f0752-0cc1-41f8-b5bf-4820a88f2d01', '724606fd-d697-4c09-82ce-b6c5099d7205', 1,
   '[{"domain": "Samenwerken en onderhandelen", "subdomain": "Suboptimale situaties"}]'::jsonb,
   '["negatief extern effect", "maatschappelijke kosten", "vervuiling", "CO₂-uitstoot", "internaliseren"]'::jsonb,
   $$Uitleggen dat vervuilende productie negatieve externe effecten en maatschappelijke kosten veroorzaakt.$$,
   $$economie-vwo-2024-i-duurzaamheid-stimuleren-vraag1.png$$, $$2p 1 Leg uit dat de productie van product A leidt tot negatieve externe effecten en maatschappelijke kosten. Geef daarbij een voorbeeld van een negatief extern effect.$$, array['1863611a-ff86-4865-9815-39f8c08ae0d5', 'f113ec91-042b-43ee-b6ce-d1575e35c4b9', '8d4083ac-0cfa-4447-841f-39af0e72e2cf', '1673c219-8c56-4795-8bc1-3d471d220e17']::uuid[]),
  ('33fdc37f-a03e-4c2f-b80a-eedcf9565f70', '724606fd-d697-4c09-82ce-b6c5099d7205', 2,
   '[{"domain": "Markt", "subdomain": "Doelmatigheid en economische politiek"}, {"domain": "Markt", "subdomain": "Vraag en aanbod"}]'::jsonb,
   '["heffing per product", "doorberekenen heffing", "evenwichtsprijs", "verschuiving aanbodlijn", "percentage berekenen"]'::jsonb,
   $$Uit een grafiek berekenen welk deel van een heffing per product in de prijs wordt doorberekend.$$,
   $$economie-vwo-2024-i-duurzaamheid-stimuleren-vraag2.png$$, $$2p 2 Bereken hoeveel procent van de heffing wordt doorberekend in de prijs van product A.$$, array['f113ec91-042b-43ee-b6ce-d1575e35c4b9']::uuid[]),
  ('98240a4c-3882-44ed-a247-243002d74305', '724606fd-d697-4c09-82ce-b6c5099d7205', 3,
   '[{"domain": "Markt", "subdomain": "Vraag en aanbod"}, {"domain": "Markt", "subdomain": "Doelmatigheid en economische politiek"}]'::jsonb,
