   $$economie-vwo-2024-i-staat-van-de-schulden-vraag10.png$$, $$2p 10 Leg uit dat een verhoging van de inkomstenbelasting leidt tot een grotere belastingwig en dat daardoor het bbp kan dalen.$$, array['bebd8bb6-6cc5-49be-b6ee-f8485c17b316']::uuid[]),
  ('12f6f43a-686c-49bc-b255-ddbc8ca9e0fa', 'f1071dac-23c9-4394-84b5-5fda988cdc6f', 11,
   '[{"domain": "Ruilen over de tijd", "subdomain": "Intertemporele ruil"}, {"domain": "Welvaart en groei", "subdomain": "Structurele groei"}]'::jsonb,
   '["publiek kapitaal", "overheidsinvesteringen", "staatsschuldquote", "economische groei", "infrastructuur"]'::jsonb,
