   $$economie-vwo-2024-i-staat-van-de-schulden-vraag11.png$$, $$2p 11 Leg de stelling van Colomba uit. Geef daarbij een voorbeeld van publiek kapitaal.$$, array['ba96f516-863c-49d0-a3bc-ac15ff72adc5']::uuid[]),
  ('7bdf2326-c54e-4aee-86cf-05b1a7292682', 'f1071dac-23c9-4394-84b5-5fda988cdc6f', 12,
   '[{"domain": "Welvaart en groei", "subdomain": "Macro-economische kringloop"}, {"domain": "Ruilen over de tijd", "subdomain": "Intertemporele ruil"}]'::jsonb,
   '["overheidssaldo", "vermogensmarkt", "rentedaling", "investeringen", "S = I + (O − B) + (E − M)"]'::jsonb,
