   $$economie-vwo-2024-i-valutaverzekering-vraag15.png$$, $$1p 15 Verklaar of Tradesure rekening moet houden met de aanwezigheid van moral hazard.$$, array['b7697fe7-4196-4d23-a069-0247eeb32345', '4fc51b9f-c5d3-4444-a2cc-c055b6a83007']::uuid[]),
  ('94ec785f-3724-44f5-b7bc-754f8ddf0f88', 'c0c89bf9-a691-41fe-97b0-655b95558f6c', 16,
   '[{"domain": "Samenwerken en onderhandelen", "subdomain": "Suboptimale situaties"}]'::jsonb,
   '["verzonken kosten", "onderhandelingskosten", "transactiekosten", "onomkeerbare kosten", "beslissing"]'::jsonb,
