   $$economie-vwo-2024-i-valutaverzekering-vraag16.png$$, $$1p 16 Beargumenteer of de onderhandelingskosten van Arco verzonken kosten zijn.$$, array['0bff82f3-93e4-4c44-adfb-00c7541b9082']::uuid[]),
  ('58f77061-680f-419d-ba44-9ec8217ebfdd', 'c0c89bf9-a691-41fe-97b0-655b95558f6c', 17,
   '[{"domain": "Risico en Informatie", "subdomain": "Risico verzekeren"}, {"domain": "Goede tijden, slechte tijden", "subdomain": "Monetair beleid en de centrale bank"}]'::jsonb,
   '["valutaverzekering", "wisselkoers berekenen", "premie berekenen", "garantiekoers", "uitkering", "depreciatie"]'::jsonb,
   $$Berekenen of een valutaverzekering voordelig is door premie en uitkering bij een wisselkoerswijziging te vergelijken.$$,
   $$economie-vwo-2024-i-valutaverzekering-vraag17.png$$, $$Gebruik bovenstaande tekst, figuur 1 en tabel 1. 2p 17 Bereken of Arco voordeel heeft gehad van het afsluiten van de valutaverzekering.$$, array['4fc51b9f-c5d3-4444-a2cc-c055b6a83007', 'f5b433de-3aed-4657-96f7-71c961358801', '78f55aa2-b6d5-416a-aa2b-d1a27c6391a8']::uuid[]),
  ('1e75d21b-0fc6-4a65-9a84-dbea566a02aa', '4c8cf0fa-7122-41aa-880a-1d8112ef7374', 18,
   '[{"domain": "Goede tijden, slechte tijden", "subdomain": "Conjunctuuranalyse aan de hand van IS-MB-GA-model"}]'::jsonb,
